{"path": "/app/ars.R", "content": "# Adaptive Rejection Sampling (Gilks & Wild, 1992)
# Implementation with input validation, log-concavity checks, and tests.

as_density_function <- function(f) {
  if (is.function(f)) return(f)
  if (is.character(f)) {
    expr <- parse(text = f)[[1]]
    env <- parent.frame()
    return(function(x) eval(expr, envir = env))
  }
  if (is.expression(f)) {
    expr <- f[[1]]
    env <- parent.frame()
    return(function(x) eval(expr, envir = env))
  }
  stop("Input density must be a function or an expression.")
}

make_log_density <- function(f, log = FALSE) {
  f_fun <- as_density_function(f)
  if (log) {
    return(function(x) {
      val <- f_fun(x)
      if (any(!is.finite(val))) stop("Log-density returned non-finite values.")
      as.numeric(val)
    })
  }
  function(x) {
    val <- f_fun(x)
    if (any(!is.finite(val))) stop("Density returned non-finite values.")
    if (any(val <= 0)) stop("Density returned non-positive values; log undefined.")
    log(val)
  }
}

numeric_derivative <- function(log_f, x, lower = -Inf, upper = Inf, eps = 1e-5) {
  x <- as.numeric(x)
  deriv <- numeric(length(x))
  for (i in seq_along(x)) {
    xi <- x[i]
    step <- eps * (abs(xi) + 1)
    left <- xi - step
    right <- xi + step
    if (left < lower) left <- xi
    if (right > upper) right <- xi
    if (left == xi && right == xi) stop("Cannot compute numerical derivative at boundary.")
    if (left == xi) {
      h0 <- log_f(xi)
      h1 <- log_f(right)
      deriv[i] <- (h1 - h0) / (right - xi)
    } else if (right == xi) {
      h0 <- log_f(xi)
      h1 <- log_f(left)
      deriv[i] <- (h0 - h1) / (xi - left)
    } else {
      h1 <- log_f(right)
      h0 <- log_f(left)
      deriv[i] <- (h1 - h0) / (right - left)
    }
  }
  if (any(!is.finite(deriv))) stop("Numerical derivative returned non-finite values.")
  deriv
}

default_initial_points <- function(lower, upper) {
  if (is.finite(lower) && is.finite(upper)) {
    span <- upper - lower
    eps <- 0.1 * span
    return(seq(lower + eps, upper - eps, length.out = 3))
  }
  if (!is.finite(lower) && is.finite(upper)) return(upper - c(3, 2, 1))
  if (is.finite(lower) && !is.finite(upper)) return(lower + c(1, 2, 3))
  c(-2, 0, 2)
}

generate_candidate_point <- function(lower, upper) {
  if (is.finite(lower) && is.finite(upper)) return(runif(1, lower, upper))
  if (is.finite(lower) && !is.finite(upper)) return(lower + rexp(1))
  if (!is.finite(lower) && is.finite(upper)) return(upper - rexp(1))
  rnorm(1)
}

ensure_initial_points <- function(log_f, initial, lower, upper) {
  initial <- sort(unique(as.numeric(initial)))
  if (length(initial) < 2) stop("At least two initial points are required.")
  if (any(initial <= lower) || any(initial >= upper)) {
    stop("Initial points must be strictly within the domain.")
  }
  h <- log_f(initial)
  valid <- is.finite(h)
  attempts <- 0
  while (any(!valid) && attempts < 200) {
    idx <- which(!valid)[1]
    initial[idx] <- generate_candidate_point(lower, upper)
    h[idx] <- log_f(initial[idx])
    valid <- is.finite(h)
    attempts <- attempts + 1
  }
  if (any(!valid)) stop("Could not find valid initial points; provide better initial values.")
  sort(unique(initial))
}

check_log_concavity <- function(x, h, dh, tol = 1e-6) {
  if (any(!is.finite(h)) || any(!is.finite(dh))) stop("Non-finite log-density values.")
  if (any(diff(x) <= 0)) stop("Support points must be strictly increasing.")
  if (any(diff(dh) > tol)) stop("Log-density is not concave: derivative increases.")
  TRUE
}

log_diff_exp <- function(a, b) {
  if (a < b) {
    tmp <- a
    a <- b
    b <- tmp
  }
  if (b == -Inf) return(a)
  a + log1p(-exp(b - a))
}

log_integral_exponential <- function(s, c, L, R, tol = 1e-12) {
  if (abs(s) < tol) {
    if (!is.finite(L) || !is.finite(R)) stop("Zero slope with infinite bound is not integrable.")
    return(c + log(R - L))
  }
  if (!is.finite(L) && s <= 0) stop("Left tail not integrable; density may be non-log-concave.")
  if (!is.finite(R) && s >= 0) stop("Right tail not integrable; density may be non-log-concave.")
  if (!is.finite(L)) {
    B <- s * R + c
    return(B - log(s))
  }
  if (!is.finite(R)) {
    A <- s * L + c
    return(A - log(-s))
  }
  A <- s * L + c
  B <- s * R + c
  if (s > 0) {
    return(log_diff_exp(B, A) - log(s))
  }
  log_diff_exp(A, B) - log(-s)
}

sample_truncated_exp <- function(s, L, R, tol = 1e-12) {
  if (abs(s) < tol) return(runif(1, L, R))
  if (!is.finite(L) && is.finite(R)) {
    if (s <= 0) stop("Left-infinite bound with non-positive slope.")
    u <- runif(1)
    return(R + log(u) / s)
  }
  if (is.finite(L) && !is.finite(R)) {
    if (s >= 0) stop("Right-infinite bound with non-negative slope.")
    u <- runif(1)
    return(L + log(1 - u) / s)
  }
  if (!is.finite(L) && !is.finite(R)) stop("Both bounds infinite; cannot sample.")
  log_base <- s * L
  log_top <- s * R
  m <- max(log_base, log_top)
  base_scaled <- exp(log_base - m)
  top_scaled <- exp(log_top - m)
  value <- base_scaled + runif(1) * (top_scaled - base_scaled)
  (log(value) + m) / s
}

compute_hull <- function(x, h, dh, lower, upper, tol = 1e-6) {
  m <- length(x)
  z <- numeric(m + 1)
  z[1] <- lower
  z[m + 1] <- upper
  for (i in 1:(m - 1)) {
    denom <- dh[i] - dh[i + 1]
    if (denom < -tol) stop("Log-density is not concave: tangent slopes increase.")
    if (abs(denom) <= tol) {
      c1 <- h[i] - dh[i] * x[i]
      c2 <- h[i + 1] - dh[i + 1] * x[i + 1]
      if (abs(c1 - c2) > 10 * tol) stop("Parallel tangents not coincident; non-log-concave density.")
      z[i + 1] <- (x[i] + x[i + 1]) / 2
    } else {
      z[i + 1] <- (h[i + 1] - h[i] - x[i + 1] * dh[i + 1] + x[i] * dh[i]) / denom
    }
    if (z[i + 1] <= x[i] - tol || z[i + 1] >= x[i + 1] + tol) {
      stop("Intersection points fall outside support interval; non-log-concave density.")
    }
  }
  if (any(diff(z) <= 0)) stop("Intersection points not increasing; non-log-concave density or poor initialization.")
  list(x = x, h = h, dh = dh, z = z)
}

eval_upper <- function(x, hull) {
  idx <- findInterval(x, hull$z, rightmost.closed = TRUE)
  idx[idx < 1] <- 1
  idx[idx > length(hull$x)] <- length(hull$x)
  s <- hull$dh[idx]
  c <- hull$h[idx] - s * hull$x[idx]
  s * x + c
}

eval_lower <- function(x, hull) {
  m <- length(hull$x)
  out <- rep(-Inf, length(x))
  idx <- findInterval(x, hull$x, rightmost.closed = TRUE)
  for (i in seq_along(x)) {
    if (idx[i] >= 1 && idx[i] < m) {
      x0 <- hull$x[idx[i]]
      x1 <- hull$x[idx[i] + 1]
      h0 <- hull$h[idx[i]]
      h1 <- hull$h[idx[i] + 1]
      out[i] <- h0 + (x[i] - x0) * (h1 - h0) / (x1 - x0)
    } else if (idx[i] == m) {
      out[i] <- hull$h[m]
    }
  }
  out
}

sample_upper <- function(hull) {
  m <- length(hull$x)
  log_weights <- numeric(m)
  for (i in 1:m) {
    s <- hull$dh[i]
    c <- hull$h[i] - s * hull$x[i]
    log_weights[i] <- log_integral_exponential(s, c, hull$z[i], hull$z[i + 1])
  }
  max_log <- max(log_weights)
  weights <- exp(log_weights - max_log)
  probs <- weights / sum(weights)
  idx <- sample.int(m, size = 1, prob = probs)
  x <- sample_truncated_exp(hull$dh[idx], hull$z[idx], hull$z[idx + 1])
  list(x = x, idx = idx)
}

validate_inputs <- function(n, f, lower, upper, initial, log, dlogf) {
  if (length(n) != 1 || !is.numeric(n) || is.na(n) || n <= 0) stop("n must be a positive number.")
  if (abs(n - round(n)) > 0) stop("n must be an integer.")
  if (!is.numeric(lower) || !is.numeric(upper) || lower >= upper) stop("Invalid domain bounds.")
  if (!is.null(dlogf) && !is.function(dlogf)) stop("dlogf must be a function.")
  log_f <- make_log_density(f, log = log)
  if (is.null(initial)) initial <- default_initial_points(lower, upper)
  initial <- ensure_initial_points(log_f, initial, lower, upper)
  list(n = as.integer(n), log_f = log_f, initial = initial,
       dlogf = dlogf, lower = lower, upper = upper)
}

ars <- function(n, f, lower = -Inf, upper = Inf, initial = NULL,
                log = FALSE, dlogf = NULL, max_iter = NULL, tol = 1e-6) {
  inputs <- validate_inputs(n, f, lower, upper, initial, log, dlogf)
  n <- inputs$n
  log_f <- inputs$log_f
  lower <- inputs$lower
  upper <- inputs$upper
  x <- inputs$initial
  if (is.null(dlogf)) {
    dlogf <- function(v) numeric_derivative(log_f, v, lower = lower, upper = upper)
  }
  h <- log_f(x)
  dh <- dlogf(x)
  check_log_concavity(x, h, dh, tol)
  if (is.null(max_iter)) max_iter <- max(1000, n * 100)
  samples <- numeric(n)
  accepted <- 0
  iter <- 0
  while (accepted < n) {
    iter <- iter + 1
    if (iter > max_iter) stop("Exceeded maximum iterations; possible non-log-concave density.")
    hull <- compute_hull(x, h, dh, lower, upper, tol = tol)
    draw <- sample_upper(hull)
    x_new <- draw$x
    u <- eval_upper(x_new, hull)
    s <- eval_lower(x_new, hull)
    w <- log(runif(1))
    if (is.finite(s) && w <= s - u) {
      accepted <- accepted + 1
      samples[accepted] <- x_new
      next
    }
    h_new <- log_f(x_new)
    if (!is.finite(h_new)) stop("Log-density returned non-finite value at sampled point.")
    if (h_new > u + tol) stop("Upper hull below log-density; non-log-concave or inaccurate derivative.")
    if (is.finite(s) && h_new < s - tol) stop("Log-density violates concavity (below chord).")
    if (w <= h_new - u) {
      accepted <- accepted + 1
      samples[accepted] <- x_new
    }
    if (all(abs(x - x_new) > 1e-10)) {
      dh_new <- dlogf(x_new)
      insert_idx <- findInterval(x_new, x) + 1
      x <- append(x, x_new, after = insert_idx - 1)
      h <- append(h, h_new, after = insert_idx - 1)
      dh <- append(dh, dh_new, after = insert_idx - 1)
      check_log_concavity(x, h, dh, tol)
    }
  }
  samples
}

test <- function() {
  set.seed(123)
  cat("Running tests for adaptive rejection sampler.\n")
  cat("Testing numerical derivative against normal log-density.\n")
  log_norm <- function(x) dnorm(x, log = TRUE)
  deriv_est <- numeric_derivative(log_norm, c(-1, 0, 1))
  deriv_true <- -c(-1, 0, 1)
  pass <- all(abs(deriv_est - deriv_true) < 0.05)
  cat(sprintf("NUMERIC_DERIVATIVE: %s (mean=%.3f, sd=%.3f)\n",
              if (pass) "PASS" else "FAIL",
              mean(deriv_est - deriv_true), sd(deriv_est - deriv_true)))
  cat("Testing upper hull envelope property.\n")
  x0 <- c(-1, 0, 1)
  h0 <- log_norm(x0)
  dh0 <- numeric_derivative(log_norm, x0)
  hull <- compute_hull(x0, h0, dh0, -Inf, Inf)
  xs <- seq(-1, 1, length.out = 5)
  u <- eval_upper(xs, hull)
  hx <- log_norm(xs)
  pass <- all(u >= hx - 1e-6)
  cat(sprintf("HULL_ENVELOPE: %s (mean=%.3f, sd=%.3f)\n",
              if (pass) "PASS" else "FAIL",
              mean(u - hx), sd(u - hx)))
  cat("Testing sampling from standard normal distribution.\n")
  n <- 2000
  samples <- ars(n, dnorm, lower = -Inf, upper = Inf, initial = c(-2, 0, 2))
  write.table(samples, "/app/normal_samples.txt", row.names = FALSE, col.names = FALSE)
  m <- mean(samples)
  s <- sd(samples)
  pass <- abs(m) < 0.1 && abs(s - 1) < 0.1
  cat(sprintf("NORMAL_SAMPLING: %s (mean=%.3f, sd=%.3f)\n",
              if (pass) "PASS" else "FAIL", m, s))
  cat("Testing sampling from exponential distribution.\n")
  samples_exp <- ars(n, function(x) dexp(x, rate = 1), lower = 0, upper = Inf,
                     initial = c(0.5, 1.0, 2.0))
  m <- mean(samples_exp)
  s <- sd(samples_exp)
  pass <- abs(m - 1) < 0.1 && abs(s - 1) < 0.1
  cat(sprintf("EXPONENTIAL_SAMPLING: %s (mean=%.3f, sd=%.3f)\n",
              if (pass) "PASS" else "FAIL", m, s))
  cat("Testing detection of non-log-concave density.\n")
  non_log_concave <- function(x) exp(x^2)
  pass <- FALSE
  tryCatch({
    ars(10, non_log_concave, lower = -Inf, upper = Inf, initial = c(-1, 0, 1))
    pass <- FALSE
  }, error = function(e) {
    pass <<- TRUE
  })
  cat(sprintf("NON_LOG_CONCAVE: %s (mean=NA, sd=NA)\n",
              if (pass) "PASS" else "FAIL"))
  invisible(TRUE)
}
"}

